-- MathLabs V5 — Fracciones y decimales
-- Requiere MathLabs V1, V2 abierto, V3 y V4.
begin;

-- Permitir modelos matemáticos visuales dentro de las lecciones.
alter table public.lesson_blocks drop constraint if exists lesson_blocks_block_type_check;
alter table public.lesson_blocks add constraint lesson_blocks_block_type_check check (block_type in ('objective','text','concepts','formula','visual','examples','common_errors','tip','summary','video','practice','prerequisites','strategy','guided_practice','math_model'));

insert into public.learning_units (id,test_type,axis,slug,title,description,icon,sort_order,is_published)
values ('school-5b-fracciones-decimales','SCHOOL','Números y operaciones','5-basico-fracciones-decimales','5.º básico · Fracciones y decimales','Segunda ruta escolar completa: fracciones propias e impropias, operaciones, equivalencias decimales y resolución de problemas.','½',2,true)
on conflict (id) do update set test_type=excluded.test_type, axis=excluded.axis, slug=excluded.slug, title=excluded.title, description=excluded.description, icon=excluded.icon, sort_order=excluded.sort_order, is_published=excluded.is_published;

insert into public.lessons (id,unit_id,slug,title,summary,objective,estimated_minutes,difficulty,sort_order,is_published,video_url,thumbnail_url,prerequisites,tags,question_filter)
values
('school-5b-frac-07','school-5b-fracciones-decimales','5b-fracciones-propias','Fracciones propias','Representa, amplifica, simplifica, compara y usa fracciones propias en modelos, conjuntos y rectas numéricas.','Comprender una fracción propia como una cantidad menor que una unidad y justificar equivalencias y comparaciones.',52,'Básico',1,true,null,null,'{}'::text[],array['5 básico','fracciones','decimales','fracciones propias']::text[],'{"course_id": "cl-5-basico", "topic_id": "topic-ma05-oa-07", "topic_slug": "fracciones-propias"}'::jsonb),
('school-5b-frac-08','school-5b-fracciones-decimales','5b-fracciones-impropias-numeros-mixtos','Fracciones impropias y números mixtos','Representa cantidades mayores que una unidad mediante fracciones impropias y números mixtos.','Transformar entre fracciones impropias y números mixtos, ubicarlos en la recta y explicar su relación con unidades completas.',50,'Básico',2,true,null,null,array['school-5b-frac-07']::text[],array['5 básico','fracciones','decimales','fracciones impropias y números mixtos']::text[],'{"course_id": "cl-5-basico", "topic_id": "topic-ma05-oa-08", "topic_slug": "fracciones-impropias-numeros-mixtos"}'::jsonb),
('school-5b-frac-09','school-5b-fracciones-decimales','5b-suma-resta-fracciones','Suma y resta de fracciones','Suma y resta fracciones propias con igual y distinto denominador, explicando por qué se requieren partes del mismo tamaño.','Resolver adiciones y sustracciones de fracciones con denominadores hasta 12 mediante modelos y fracciones equivalentes.',58,'Básico',3,true,null,null,array['school-5b-frac-08']::text[],array['5 básico','fracciones','decimales','suma y resta de fracciones']::text[],'{"course_id": "cl-5-basico", "topic_id": "topic-ma05-oa-09", "topic_slug": "suma-resta-de-fracciones"}'::jsonb),
('school-5b-frac-10','school-5b-fracciones-decimales','5b-fracciones-decimales-equivalentes','Fracciones y decimales equivalentes','Relaciona fracciones con denominadores 2, 4, 5 y 10 con sus representaciones decimales.','Transformar entre fracciones y decimales finitos usando equivalencias con décimos y centésimos.',48,'Básico',4,true,null,null,array['school-5b-frac-09']::text[],array['5 básico','fracciones','decimales','fracciones y decimales equivalentes']::text[],'{"course_id": "cl-5-basico", "topic_id": "topic-ma05-oa-10", "topic_slug": "fracciones-decimales-equivalentes"}'::jsonb),
('school-5b-frac-11','school-5b-fracciones-decimales','5b-comparacion-decimales','Comparación de decimales','Compara y ordena números decimales hasta la milésima usando valor posicional, ceros equivalentes y recta numérica.','Justificar el orden de números decimales mediante el valor de unidades, décimos, centésimos y milésimos.',46,'Básico',5,true,null,null,array['school-5b-frac-10']::text[],array['5 básico','fracciones','decimales','comparación de decimales']::text[],'{"course_id": "cl-5-basico", "topic_id": "topic-ma05-oa-11", "topic_slug": "comparacion-de-decimales"}'::jsonb),
('school-5b-frac-12','school-5b-fracciones-decimales','5b-suma-resta-decimales','Suma y resta de decimales','Suma y resta decimales hasta la milésima usando valor posicional, estimación y contextos de dinero o medición.','Resolver adiciones y sustracciones decimales alineando posiciones y explicando el significado de cada cifra.',54,'Básico',6,true,null,null,array['school-5b-frac-11']::text[],array['5 básico','fracciones','decimales','suma y resta de decimales']::text[],'{"course_id": "cl-5-basico", "topic_id": "topic-ma05-oa-12", "topic_slug": "suma-resta-de-decimales"}'::jsonb),
('school-5b-frac-13','school-5b-fracciones-decimales','5b-problemas-fracciones-decimales','Problemas con fracciones y decimales','Resuelve problemas de una y varias etapas que combinan fracciones propias y números decimales.','Seleccionar representaciones y operaciones adecuadas para resolver problemas contextualizados con fracciones y decimales.',60,'Básico',7,true,null,null,array['school-5b-frac-12']::text[],array['5 básico','fracciones','decimales','problemas con fracciones y decimales']::text[],'{"course_id": "cl-5-basico", "topic_id": "topic-ma05-oa-13", "topic_slug": "problemas-con-fracciones-decimales"}'::jsonb)
