delete from public.lesson_blocks where lesson_id in ('school-5b-frac-07','school-5b-frac-08','school-5b-frac-09','school-5b-frac-10','school-5b-frac-11','school-5b-frac-12','school-5b-frac-13');
insert into public.lesson_blocks (lesson_id,block_type,title,content,data,sort_order)
select lesson_id,block_type,title,content,data,sort_order
from jsonb_to_recordset($blocks$[{"lesson_id":"school-5b-frac-07","block_type":"objective","title":"Meta de aprendizaje","content":"Comprender una fracción propia como una cantidad menor que una unidad y justificar equivalencias y comparaciones.","data":{},"sort_order":1},{"lesson_id":"school-5b-frac-07","block_type":"prerequisites","title":"Antes de comenzar","content":"Revisa estas ideas antes de avanzar.","data":{"items":[{"title":"División en partes iguales","body":"La unidad debe separarse en partes del mismo tamaño."},{"title":"Multiplicación y división","body":"Se usan para amplificar, simplificar y calcular una fracción de una cantidad."},{"title":"Orden numérico","body":"Las fracciones también ocupan posiciones en la recta numérica."}]},"sort_order":2},{"lesson_id":"school-5b-frac-07","block_type":"text","title":"Comprensión profunda","content":"Una fracción propia representa una cantidad mayor o igual que cero y menor que una unidad. El denominador indica en cuántas partes iguales se divide la unidad; el numerador indica cuántas de esas partes se consideran.\n\nDos fracciones pueden escribirse de manera distinta y representar exactamente la misma cantidad. Amplificar significa multiplicar numerador y denominador por el mismo número; simplificar significa dividirlos por un divisor común. En ambos casos, la cantidad representada no cambia.\n\nPara comparar fracciones conviene elegir una estrategia según su estructura: igual denominador, igual numerador, comparación con un referente como 1/2, denominador común o representación decimal. Una regla memorizada no reemplaza la comprensión del tamaño de las partes.","data":{},"sort_order":3},{"lesson_id":"school-5b-frac-07","block_type":"concepts","title":"Conceptos fundamentales","content":"","data":{"items":[{"title":"Unidad","body":"Es el todo que se toma como referencia; debe permanecer igual durante la comparación."},{"title":"Numerador","body":"Cuenta las partes consideradas."},{"title":"Denominador","body":"Indica el número total de partes iguales de la unidad."},{"title":"Equivalencia","body":"Dos fracciones equivalentes ocupan el mismo punto en la recta numérica."}]},"sort_order":4},{"lesson_id":"school-5b-frac-07","block_type":"math_model","title":"Modelo matemático visual","content":"","data":{"mode":"fraction_equivalence","numerator":2,"denominator":3,"multiplier":2,"caption":"2/3 y 4/6 cubren la misma porción de una unidad."},"sort_order":5},{"lesson_id":"school-5b-frac-07","block_type":"formula","title":"Relaciones y procedimientos","content":"","data":{"items":["a/b = (a·k)/(b·k), con k distinto de 0","a/b = (a÷k)/(b÷k), cuando k divide a ambos","Mismo denominador: mayor numerador → mayor fracción","Mismo numerador: menor denominador → mayor fracción","Fracción de una cantidad: (a/b)·cantidad"]},"sort_order":6},{"lesson_id":"school-5b-frac-07","block_type":"strategy","title":"Método MathLabs","content":"Aplica estos pasos antes de responder.","data":{"steps":[{"title":"1. Identifica la unidad","body":"Comprueba que todas las fracciones se refieran al mismo todo."},{"title":"2. Observa la estructura","body":"Busca igual numerador, igual denominador o un referente útil."},{"title":"3. Elige representación","body":"Usa barra, recta, conjunto o denominador común."},{"title":"4. Calcula sin cambiar la cantidad","body":"Amplifica o simplifica ambos términos por el mismo factor."},{"title":"5. Justifica","body":"Explica por qué la fracción es mayor, menor o equivalente."}]},"sort_order":7},{"lesson_id":"school-5b-frac-07","block_type":"examples","title":"Ejercicios resueltos: nivel fundamental","content":"","data":{"examples":[{"problem":"Una barra está dividida en 8 partes iguales y 3 están pintadas. ¿Qué fracción representa?","steps":["El total de partes iguales es 8, por lo que ese es el denominador.","Las partes pintadas son 3, por lo que ese es el numerador."],"answer":"3/8","skill":"Representar","level":"Fundamental","strategy":"Primero identifica el total de partes iguales.","verification":"3 es menor que 8, por lo que la fracción es propia."},{"problem":"Amplifica 2/3 para obtener denominador 12.","steps":["Para pasar de 3 a 12 se multiplica por 4.","Multiplicamos también el numerador: 2·4=8."],"answer":"2/3 = 8/12","skill":"Representar","level":"Fundamental","strategy":"El mismo factor debe aplicarse arriba y abajo.","verification":"8÷12 produce la misma cantidad que 2÷3."}]},"sort_order":8},{"lesson_id":"school-5b-frac-07","block_type":"examples","title":"Ejercicios resueltos: nivel intermedio","content":"","data":{"examples":[{"problem":"Simplifica 12/18.","steps":["El máximo divisor común de 12 y 18 es 6.","Dividimos ambos términos por 6.","12÷6=2 y 18÷6=3."],"answer":"2/3","skill":"Resolver problemas","level":"Intermedio","strategy":"Busca un divisor común mayor que 1.","verification":"2/3 amplificada por 6 vuelve a 12/18."},{"problem":"Compara 5/8 y 2/3.","steps":["Usamos denominador común 24.","5/8=15/24 y 2/3=16/24.","16/24 es mayor que 15/24."],"answer":"5/8 < 2/3","skill":"Argumentar","level":"Intermedio","strategy":"Transforma a partes del mismo tamaño.","verification":"Los decimales aproximados 0,625 y 0,667 confirman el orden."}]},"sort_order":9},{"lesson_id":"school-5b-frac-07","block_type":"examples","title":"Ejercicios resueltos: desafío","content":"","data":{"examples":[{"problem":"Calcula 3/5 de 40 estudiantes.","steps":["Dividimos 40 en 5 grupos iguales: 40÷5=8.","Tomamos 3 grupos: 3·8=24."],"answer":"24 estudiantes","skill":"Modelar","level":"Desafío","strategy":"Primero calcula cuánto corresponde a una quinta parte.","verification":"24/40 se simplifica a 3/5."},{"problem":"Un estudiante afirma: «Si el denominador es mayor, la fracción es mayor». Refútalo con 1/3 y 1/6.","steps":["Ambas fracciones tienen el mismo numerador.","Al dividir la misma unidad en 6 partes, cada parte es menor que al dividirla en 3.","Por eso 1/3 es mayor que 1/6."],"answer":"La afirmación es falsa: 1/3 > 1/6","skill":"Argumentar","level":"Desafío","strategy":"Compara partes de una misma unidad.","verification":"En decimal, 1/3≈0,333 y 1/6≈0,167."}]},"sort_order":10},{"lesson_id":"school-5b-frac-07","block_type":"guided_practice","title":"Práctica guiada","content":"Intenta cada problema antes de abrir las pistas.","data":{"exercises":[{"problem":"Amplifica 3/5 hasta obtener denominador 20.","hints":["¿Por cuánto se multiplica 5 para obtener 20?","Aplica el mismo factor al numerador."],"steps":["5·4=20.","3·4=12."],"answer":"12/20","skill":"Representar"},{"problem":"Simplifica 15/25.","hints":["Busca un divisor común.","Ambos son divisibles por 5."],"steps":["15÷5=3.","25÷5=5."],"answer":"3/5","skill":"Resolver problemas"},{"problem":"¿Cuál es mayor: 4/7 o 4/9?","hints":["Tienen el mismo numerador.","Con menos partes en la unidad, cada parte es mayor."],"steps":["Séptimos son mayores que novenos.","Por eso 4/7>4/9."],"answer":"4/7","skill":"Argumentar"}]},"sort_order":11},{"lesson_id":"school-5b-frac-07","block_type":"common_errors","title":"Errores frecuentes","content":"","data":{"items":[{"title":"Contar partes de distinto tamaño","description":"Una fracción solo describe correctamente una unidad dividida en partes iguales."},{"title":"Amplificar solo el numerador","description":"Eso cambia la cantidad; numerador y denominador deben multiplicarse por el mismo factor."},{"title":"Creer que un denominador mayor siempre da una fracción mayor","description":"Con igual numerador, ocurre lo contrario."},{"title":"Comparar dibujos con unidades diferentes","description":"Dos barras deben tener el mismo tamaño total para comparar sus fracciones."}]},"sort_order":12},{"lesson_id":"school-5b-frac-07","block_type":"summary","title":"Dominio esperado","content":"","data":{"items":["Interpretas numerador, denominador y unidad.","Construyes fracciones equivalentes.","Simplificas sin alterar la cantidad.","Comparas fracciones usando más de una estrategia.","Calculas una fracción de una cantidad."]},"sort_order":13},{"lesson_id":"school-5b-frac-07","block_type":"practice","title":"Practica este tema","content":"Continúa con una sesión de ocho preguntas y retroalimentación inmediata.","data":{},"sort_order":14},{"lesson_id":"school-5b-frac-08","block_type":"objective","title":"Meta de aprendizaje","content":"Transformar entre fracciones impropias y números mixtos, ubicarlos en la recta y explicar su relación con unidades completas.","data":{},"sort_order":1},{"lesson_id":"school-5b-frac-08","block_type":"prerequisites","title":"Antes de comenzar","content":"Revisa estas ideas antes de avanzar.","data":{"items":[{"title":"Fracciones propias","body":"Cada parte fraccionaria debe conservar el mismo denominador."},{"title":"División con resto","body":"El cociente indica unidades completas y el resto la parte fraccionaria."},{"title":"Recta numérica","body":"Las cantidades mayores que 1 se ubican entre enteros consecutivos."}]},"sort_order":2},{"lesson_id":"school-5b-frac-08","block_type":"text","title":"Comprensión profunda","content":"Una fracción impropia tiene numerador mayor o igual que el denominador. Puede representar una unidad exacta o una cantidad mayor que una unidad. Por ejemplo, 7/4 significa siete cuartos: cuatro cuartos forman una unidad y quedan tres cuartos.\n\nUn número mixto combina una parte entera y una fracción propia. Las expresiones 7/4 y 1 3/4 representan la misma posición en la recta numérica.\n\nPara transformar una fracción impropia en número mixto se divide el numerador por el denominador. Para volver a fracción impropia se multiplican las unidades completas por el denominador y se suma el numerador de la parte fraccionaria.","data":{},"sort_order":3},{"lesson_id":"school-5b-frac-08","block_type":"concepts","title":"Conceptos fundamentales","content":"","data":{"items":[{"title":"Fracción impropia","body":"Su numerador es mayor o igual que el denominador."},{"title":"Número mixto","body":"Combina unidades completas y una fracción propia."},{"title":"Cociente","body":"Indica cuántas unidades completas se forman."},{"title":"Resto","body":"Se convierte en el numerador de la parte fraccionaria."}]},"sort_order":4},{"lesson_id":"school-5b-frac-08","block_type":"math_model","title":"Modelo matemático visual","content":"","data":{"mode":"mixed_number","wholes":1,"numerator":3,"denominator":4,"caption":"Siete cuartos forman una unidad completa y tres cuartos adicionales."},"sort_order":5},{"lesson_id":"school-5b-frac-08","block_type":"formula","title":"Relaciones y procedimientos","content":"","data":{"items":["a/b = cociente + resto/b","Número mixto a impropia: (entero·denominador + numerador)/denominador","b/b = 1 unidad","2b/b = 2 unidades","La parte fraccionaria del mixto debe ser propia"]},"sort_order":6},{"lesson_id":"school-5b-frac-08","block_type":"strategy","title":"Método MathLabs","content":"Aplica estos pasos antes de responder.","data":{"steps":[{"title":"1. Cuenta unidades completas","body":"Agrupa tantas partes como indique el denominador."},{"title":"2. Divide numerador por denominador","body":"Registra cociente y resto."},{"title":"3. Conserva el denominador","body":"El tamaño de las partes no cambia."},{"title":"4. Ubica entre enteros","body":"El número mixto indica claramente el intervalo."},{"title":"5. Comprueba al convertir de vuelta","body":"La fracción impropia obtenida debe coincidir con la inicial."}]},"sort_order":7},{"lesson_id":"school-5b-frac-08","block_type":"examples","title":"Ejercicios resueltos: nivel fundamental","content":"","data":{"examples":[{"problem":"Convierte 7/4 a número mixto.","steps":["7÷4=1 resto 3.","El cociente es la parte entera.","El resto queda como numerador sobre 4."],"answer":"1 3/4","skill":"Representar","level":"Fundamental","strategy":"Forma primero grupos de cuatro cuartos.","verification":"1 3/4=(1·4+3)/4=7/4."},{"problem":"Convierte 2 3/5 a fracción impropia.","steps":["Dos unidades equivalen a 10/5.","Agregamos 3/5.","10/5+3/5=13/5."],"answer":"13/5","skill":"Representar","level":"Fundamental","strategy":"Multiplica entero por denominador y suma el numerador.","verification":"13÷5=2 resto 3."}]},"sort_order":8},{"lesson_id":"school-5b-frac-08","block_type":"examples","title":"Ejercicios resueltos: nivel intermedio","content":"","data":{"examples":[{"problem":"¿Entre qué enteros se ubica 9/4?","steps":["9÷4=2 resto 1.","9/4=2 1/4.","Por eso se ubica después de 2 y antes de 3."],"answer":"Entre 2 y 3","skill":"Argumentar","level":"Intermedio","strategy":"Convierte temporalmente a mixto.","verification":"2<2 1/4<3."},{"problem":"Compara 11/6 y 1 4/5.","steps":["11/6=1 5/6.","Comparamos las partes 5/6 y 4/5.","5/6=25/30 y 4/5=24/30."],"answer":"11/6 > 1 4/5","skill":"Argumentar","level":"Intermedio","strategy":"Expresa ambas cantidades con la misma estructura.","verification":"Sus decimales aproximados son 1,833 y 1,8."}]},"sort_order":9},{"lesson_id":"school-5b-frac-08","block_type":"examples","title":"Ejercicios resueltos: desafío","content":"","data":{"examples":[{"problem":"Una cinta mide 13/4 metros. Exprésala como número mixto.","steps":["13÷4=3 resto 1.","Se forman 3 metros completos y queda un cuarto."],"answer":"3 1/4 m","skill":"Modelar","level":"Desafío","strategy":"Interpreta el cociente como unidades completas.","verification":"3 1/4=3,25 y 13/4=3,25."},{"problem":"Descompón 17/5 como suma de unidades y una fracción propia.","steps":["Cada 5/5 forma una unidad.","17/5 contiene 15/5 y sobran 2/5.","15/5=3."],"answer":"3 + 2/5","skill":"Representar","level":"Desafío","strategy":"Busca el múltiplo del denominador más cercano sin superar el numerador.","verification":"3+2/5=15/5+2/5=17/5."}]},"sort_order":10},{"lesson_id":"school-5b-frac-08","block_type":"guided_practice","title":"Práctica guiada","content":"Intenta cada problema antes de abrir las pistas.","data":{"exercises":[{"problem":"Convierte 10/3 a número mixto.","hints":["Divide 10 entre 3.","Usa el resto como numerador."],"steps":["10÷3=3 resto 1.","El denominador sigue siendo 3."],"answer":"3 1/3","skill":"Representar"},{"problem":"Convierte 4 2/7 a fracción impropia.","hints":["Multiplica 4 por 7.","Suma 2."],"steps":["4·7=28.","28+2=30."],"answer":"30/7","skill":"Representar"},{"problem":"Ubica 14/5 entre dos enteros.","hints":["Convierte a mixto.","14÷5=2 resto 4."],"steps":["14/5=2 4/5.","Está entre 2 y 3."],"answer":"Entre 2 y 3","skill":"Argumentar"}]},"sort_order":11},{"lesson_id":"school-5b-frac-08","block_type":"common_errors","title":"Errores frecuentes","content":"","data":{"items":[{"title":"Cambiar el denominador al convertir","description":"Las partes conservan el mismo tamaño."},{"title":"Usar el cociente como numerador","description":"El cociente es la parte entera; el resto es el numerador."},{"title":"Sumar entero y numerador sin multiplicar","description":"Para convertir un mixto primero hay que expresar las unidades en partes del denominador."},{"title":"Dejar una fracción impropia en la parte fraccionaria","description":"Un número mixto normalizado debe tener una fracción propia."}]},"sort_order":12},{"lesson_id":"school-5b-frac-08","block_type":"summary","title":"Dominio esperado","content":"","data":{"items":["Reconoces cantidades mayores que una unidad.","Transformas impropias en números mixtos.","Transformas números mixtos en impropias.","Ubicas estas cantidades en la recta numérica.","Compruebas equivalencias mediante conversión inversa."]},"sort_order":13},{"lesson_id":"school-5b-frac-08","block_type":"practice","title":"Practica este tema","content":"Continúa con una sesión de ocho preguntas y retroalimentación inmediata.","data":{},"sort_order":14},{"lesson_id":"school-5b-frac-09","block_type":"objective","title":"Meta de aprendizaje","content":"Resolver adiciones y sustracciones de fracciones con denominadores hasta 12 mediante modelos y fracciones equivalentes.","data":{},"sort_order":1},{"lesson_id":"school-5b-frac-09","block_type":"prerequisites","title":"Antes de comenzar","content":"Revisa estas ideas antes de avanzar.","data":{"items":[{"title":"Fracciones equivalentes","body":"Permiten expresar cantidades con partes del mismo tamaño."},{"title":"Múltiplos","body":"Ayudan a encontrar un denominador común."},{"title":"Simplificación","body":"La respuesta final puede expresarse en forma irreducible."}]},"sort_order":2},{"lesson_id":"school-5b-frac-09","block_type":"text","title":"Comprensión profunda","content":"Sumar fracciones significa reunir cantidades expresadas con partes de igual tamaño. Cuando los denominadores son iguales, se suman o restan los numeradores y se conserva el denominador.\n\nCuando los denominadores son distintos, no se pueden combinar directamente las partes porque tienen tamaños diferentes. Primero hay que buscar fracciones equivalentes con un denominador común. El mínimo común múltiplo suele producir cálculos más pequeños.\n\nDespués de operar, conviene simplificar y comprobar si la respuesta es razonable. La suma de dos fracciones positivas debe ser mayor que cada sumando; en una resta, el resultado debe ser menor que la cantidad inicial.","data":{},"sort_order":3},{"lesson_id":"school-5b-frac-09","block_type":"concepts","title":"Conceptos fundamentales","content":"","data":{"items":[{"title":"Denominador común","body":"Permite expresar todas las partes con el mismo tamaño."},{"title":"Mínimo común múltiplo","body":"Es una opción eficiente para construir el denominador común."},{"title":"Numeradores","body":"Se combinan solo después de igualar denominadores."},{"title":"Simplificación final","body":"Entrega una representación equivalente más sencilla."}]},"sort_order":4},{"lesson_id":"school-5b-frac-09","block_type":"math_model","title":"Modelo matemático visual","content":"","data":{"mode":"fraction_addition","left_numerator":1,"left_denominator":3,"right_numerator":1,"right_denominator":4,"result_numerator":7,"result_denominator":12,"caption":"Tercios y cuartos se convierten en doceavos antes de sumarse."},"sort_order":5},{"lesson_id":"school-5b-frac-09","block_type":"formula","title":"Relaciones y procedimientos","content":"","data":{"items":["a/b + c/b = (a+c)/b","a/b − c/b = (a−c)/b","a/b + c/d = (ad+bc)/(bd)","a/b − c/d = (ad−bc)/(bd)","Simplifica numerador y denominador por un divisor común"]},"sort_order":6},{"lesson_id":"school-5b-frac-09","block_type":"strategy","title":"Método MathLabs","content":"Aplica estos pasos antes de responder.","data":{"steps":[{"title":"1. Revisa denominadores","body":"Si son iguales, opera directamente los numeradores."},{"title":"2. Busca un denominador común","body":"Prefiere el mínimo común múltiplo cuando sea sencillo."},{"title":"3. Construye equivalencias","body":"Amplifica cada fracción sin cambiar su valor."},{"title":"4. Opera numeradores","body":"Conserva el denominador común."},{"title":"5. Simplifica y estima","body":"Comprueba el tamaño de la respuesta."}]},"sort_order":7},{"lesson_id":"school-5b-frac-09","block_type":"examples","title":"Ejercicios resueltos: nivel fundamental","content":"","data":{"examples":[{"problem":"Calcula 3/8 + 2/8.","steps":["Los denominadores son iguales.","Sumamos numeradores: 3+2=5.","Conservamos el denominador 8."],"answer":"5/8","skill":"Resolver problemas","level":"Fundamental","strategy":"Partes del mismo tamaño pueden combinarse directamente.","verification":"5/8 es mayor que 3/8 y 2/8."},{"problem":"Calcula 7/10 − 3/10.","steps":["Los denominadores son iguales.","Restamos numeradores: 7−3=4.","4/10 se simplifica dividiendo por 2."],"answer":"2/5","skill":"Resolver problemas","level":"Fundamental","strategy":"Simplifica al final.","verification":"2/5=4/10."}]},"sort_order":8},{"lesson_id":"school-5b-frac-09","block_type":"examples","title":"Ejercicios resueltos: nivel intermedio","content":"","data":{"examples":[{"problem":"Calcula 1/3 + 1/4.","steps":["El mínimo común múltiplo de 3 y 4 es 12.","1/3=4/12 y 1/4=3/12.","4/12+3/12=7/12."],"answer":"7/12","skill":"Resolver problemas","level":"Intermedio","strategy":"Convierte a partes del mismo tamaño.","verification":"7/12≈0,583, mayor que ambos sumandos."},{"problem":"Calcula 5/6 − 1/4.","steps":["El m.c.m. de 6 y 4 es 12.","5/6=10/12 y 1/4=3/12.","10/12−3/12=7/12."],"answer":"7/12","skill":"Resolver problemas","level":"Intermedio","strategy":"No restes denominadores.","verification":"7/12≈0,583, menor que 5/6."}]},"sort_order":9},{"lesson_id":"school-5b-frac-09","block_type":"examples","title":"Ejercicios resueltos: desafío","content":"","data":{"examples":[{"problem":"En la mañana se recorrió 2/5 de una ruta y en la tarde 3/10. ¿Qué fracción se recorrió?","steps":["2/5=4/10.","4/10+3/10=7/10."],"answer":"7/10 de la ruta","skill":"Modelar","level":"Desafío","strategy":"Expresa ambas partes respecto de la misma ruta.","verification":"Queda 3/10, por lo que el total recorrido es menor que 1."},{"problem":"Un estanque tenía 7/8 de su capacidad y se usó 1/3 de la capacidad total. ¿Qué fracción quedó?","steps":["El denominador común de 8 y 3 es 24.","7/8=21/24 y 1/3=8/24.","21/24−8/24=13/24."],"answer":"13/24","skill":"Modelar","level":"Desafío","strategy":"Aclara que ambas fracciones se refieren a la capacidad total.","verification":"13/24 es positivo y menor que 7/8."}]},"sort_order":10},{"lesson_id":"school-5b-frac-09","block_type":"guided_practice","title":"Práctica guiada","content":"Intenta cada problema antes de abrir las pistas.","data":{"exercises":[{"problem":"Calcula 4/9 + 2/9.","hints":["Los denominadores ya son iguales.","Suma los numeradores."],"steps":["4+2=6.","6/9 se simplifica por 3."],"answer":"2/3","skill":"Resolver problemas"},{"problem":"Calcula 1/2 + 1/5.","hints":["Busca el m.c.m. de 2 y 5.","Convierte a décimos."],"steps":["1/2=5/10.","1/5=2/10.","La suma es 7/10."],"answer":"7/10","skill":"Resolver problemas"},{"problem":"Calcula 3/4 − 1/6.","hints":["El m.c.m. de 4 y 6 es 12.","Expresa ambas como doceavos."],"steps":["3/4=9/12.","1/6=2/12.","9/12−2/12=7/12."],"answer":"7/12","skill":"Resolver problemas"}]},"sort_order":11},{"lesson_id":"school-5b-frac-09","block_type":"common_errors","title":"Errores frecuentes","content":"","data":{"items":[{"title":"Sumar denominadores","description":"Los denominadores indican el tamaño de las partes y no se suman."},{"title":"Usar un denominador común sin amplificar numeradores","description":"La equivalencia exige transformar ambos términos."},{"title":"Confundir m.c.m. con suma de denominadores","description":"El producto siempre sirve, pero el m.c.m. suele ser más eficiente."},{"title":"No simplificar","description":"Una respuesta correcta puede expresarse de manera más sencilla."}]},"sort_order":12},{"lesson_id":"school-5b-frac-09","block_type":"summary","title":"Dominio esperado","content":"","data":{"items":["Explicas por qué se necesitan partes iguales.","Operas directamente con denominadores iguales.","Encuentras denominadores comunes.","Construyes fracciones equivalentes.","Simplificas y compruebas el resultado."]},"sort_order":13},{"lesson_id":"school-5b-frac-09","block_type":"practice","title":"Practica este tema","content":"Continúa con una sesión de ocho preguntas y retroalimentación inmediata.","data":{},"sort_order":14},{"lesson_id":"school-5b-frac-10","block_type":"objective","title":"Meta de aprendizaje","content":"Transformar entre fracciones y decimales finitos usando equivalencias con décimos y centésimos.","data":{},"sort_order":1},{"lesson_id":"school-5b-frac-10","block_type":"prerequisites","title":"Antes de comenzar","content":"Revisa estas ideas antes de avanzar.","data":{"items":[{"title":"Fracciones equivalentes","body":"Permiten obtener denominadores 10 o 100."},{"title":"Décimos y centésimos","body":"Son posiciones decimales y también partes de una unidad."},{"title":"División","body":"Una fracción representa el cociente entre numerador y denominador."}]},"sort_order":2},{"lesson_id":"school-5b-frac-10","block_type":"text","title":"Comprensión profunda","content":"Una fracción y un decimal pueden representar exactamente la misma cantidad. Por ejemplo, 1/2, 5/10 y 0,5 ocupan el mismo punto de la recta numérica.\n\nCon denominadores 2, 4, 5 y 10 es posible construir fácilmente fracciones equivalentes con denominador 10 o 100. Eso permite leer directamente la representación decimal.\n\nTambién se puede dividir el numerador por el denominador. Sin embargo, en este nivel conviene comprender primero la relación con décimos y centésimos para que el decimal conserve un significado visual y posicional.","data":{},"sort_order":3},{"lesson_id":"school-5b-frac-10","block_type":"concepts","title":"Conceptos fundamentales","content":"","data":{"items":[{"title":"Décimo","body":"Una de diez partes iguales: 1/10=0,1."},{"title":"Centésimo","body":"Una de cien partes iguales: 1/100=0,01."},{"title":"Decimal finito","body":"Tiene una cantidad limitada de cifras decimales."},{"title":"Representaciones equivalentes","body":"Fracción, decimal y modelo pueden expresar la misma cantidad."}]},"sort_order":4},{"lesson_id":"school-5b-frac-10","block_type":"math_model","title":"Modelo matemático visual","content":"","data":{"mode":"decimal_grid","hundredths":75,"caption":"75 de 100 cuadrados representan 75/100, 3/4 y 0,75."},"sort_order":5},{"lesson_id":"school-5b-frac-10","block_type":"formula","title":"Relaciones y procedimientos","content":"","data":{"items":["1/2 = 5/10 = 0,5","1/4 = 25/100 = 0,25","3/4 = 75/100 = 0,75","1/5 = 2/10 = 0,2","a/10 = 0,a"]},"sort_order":6},{"lesson_id":"school-5b-frac-10","block_type":"strategy","title":"Método MathLabs","content":"Aplica estos pasos antes de responder.","data":{"steps":[{"title":"1. Observa el denominador","body":"Decide si conviene llegar a 10 o 100."},{"title":"2. Amplifica","body":"Transforma sin cambiar la cantidad."},{"title":"3. Lee el valor posicional","body":"Décimos usan una cifra; centésimos, dos."},{"title":"4. Comprueba con división","body":"Numerador÷denominador debe producir el mismo decimal."},{"title":"5. Relaciona con un modelo","body":"Ubica la cantidad en una barra, cuadrícula o recta."}]},"sort_order":7},{"lesson_id":"school-5b-frac-10","block_type":"examples","title":"Ejercicios resueltos: nivel fundamental","content":"","data":{"examples":[{"problem":"Convierte 1/2 a decimal.","steps":["Amplificamos por 5: 1/2=5/10.","Cinco décimos se escriben 0,5."],"answer":"0,5","skill":"Representar","level":"Fundamental","strategy":"Busca denominador 10.","verification":"1÷2=0,5."},{"problem":"Convierte 3/4 a decimal.","steps":["Amplificamos por 25: 3/4=75/100.","Setenta y cinco centésimos se escriben 0,75."],"answer":"0,75","skill":"Representar","level":"Fundamental","strategy":"Busca denominador 100.","verification":"0,75·4=3."}]},"sort_order":8},{"lesson_id":"school-5b-frac-10","block_type":"examples","title":"Ejercicios resueltos: nivel intermedio","content":"","data":{"examples":[{"problem":"Convierte 2/5 a decimal.","steps":["Amplificamos por 2: 2/5=4/10.","Cuatro décimos se escriben 0,4."],"answer":"0,4","skill":"Representar","level":"Intermedio","strategy":"Los quintos se convierten fácilmente en décimos.","verification":"2÷5=0,4."},{"problem":"Escribe 0,7 como fracción irreducible.","steps":["0,7 significa siete décimos: 7/10.","7 y 10 no tienen divisor común mayor que 1."],"answer":"7/10","skill":"Representar","level":"Intermedio","strategy":"Nombra la posición decimal.","verification":"7÷10=0,7."}]},"sort_order":9},{"lesson_id":"school-5b-frac-10","block_type":"examples","title":"Ejercicios resueltos: desafío","content":"","data":{"examples":[{"problem":"Compara 0,25 y 1/4.","steps":["1/4=25/100.","25/100 se escribe 0,25.","Representan la misma cantidad."],"answer":"0,25 = 1/4","skill":"Argumentar","level":"Desafío","strategy":"Transforma ambas a centésimos.","verification":"Ambas cubren 25 de 100 partes."},{"problem":"Un recipiente está lleno en 0,6 de su capacidad. Exprésalo como fracción irreducible.","steps":["0,6=6/10.","Simplificamos por 2.","6/10=3/5."],"answer":"3/5","skill":"Modelar","level":"Desafío","strategy":"Convierte el decimal según su valor posicional.","verification":"3÷5=0,6."}]},"sort_order":10},{"lesson_id":"school-5b-frac-10","block_type":"guided_practice","title":"Práctica guiada","content":"Intenta cada problema antes de abrir las pistas.","data":{"exercises":[{"problem":"Convierte 4/5 a decimal.","hints":["Convierte quintos en décimos.","Multiplica numerador y denominador por 2."],"steps":["4/5=8/10.","8/10=0,8."],"answer":"0,8","skill":"Representar"},{"problem":"Convierte 0,45 a fracción.","hints":["Son 45 centésimos.","Simplifica 45/100."],"steps":["45/100 se divide por 5.","Resulta 9/20."],"answer":"9/20","skill":"Representar"},{"problem":"¿Son equivalentes 0,5 y 2/4?","hints":["Convierte 2/4 a una fracción más simple.","Relaciona 1/2 con décimos."],"steps":["2/4=1/2.","1/2=0,5."],"answer":"Sí, son equivalentes","skill":"Argumentar"}]},"sort_order":11},{"lesson_id":"school-5b-frac-10","block_type":"common_errors","title":"Errores frecuentes","content":"","data":{"items":[{"title":"Escribir 3/4 como 0,34","description":"Numerador y denominador no se colocan como cifras consecutivas."},{"title":"Confundir décimos con centésimos","description":"0,5=5/10, mientras 0,05=5/100."},{"title":"Agregar ceros sin comprender","description":"0,5 y 0,50 son equivalentes porque ambos representan la mitad."},{"title":"No simplificar la fracción decimal","description":"45/100 puede expresarse como 9/20."}]},"sort_order":12},{"lesson_id":"school-5b-frac-10","block_type":"summary","title":"Dominio esperado","content":"","data":{"items":["Relacionas décimos y centésimos con fracciones.","Conviertes fracciones de denominador 2, 4, 5 y 10.","Transformas decimales finitos en fracciones.","Reconoces representaciones equivalentes.","Compruebas mediante división o modelos."]},"sort_order":13},{"lesson_id":"school-5b-frac-10","block_type":"practice","title":"Practica este tema","content":"Continúa con una sesión de ocho preguntas y retroalimentación inmediata.","data":{},"sort_order":14},{"lesson_id":"school-5b-frac-11","block_type":"objective","title":"Meta de aprendizaje","content":"Justificar el orden de números decimales mediante el valor de unidades, décimos, centésimos y milésimos.","data":{},"sort_order":1},{"lesson_id":"school-5b-frac-11","block_type":"prerequisites","title":"Antes de comenzar","content":"Revisa estas ideas antes de avanzar.","data":{"items":[{"title":"Valor posicional","body":"Cada posición a la derecha vale diez veces menos."},{"title":"Fracciones decimales","body":"Décimos, centésimos y milésimos son partes de la unidad."},{"title":"Recta numérica","body":"El número ubicado más a la derecha es mayor."}]},"sort_order":2},{"lesson_id":"school-5b-frac-11","block_type":"text","title":"Comprensión profunda","content":"Para comparar decimales se compara primero la parte entera. Si es igual, se observan décimos, luego centésimos y finalmente milésimos.\n\nLos ceros a la derecha de la última cifra decimal no cambian el valor: 0,7=0,70=0,700. Agregarlos puede ayudar a alinear posiciones antes de comparar.\n\nLa cantidad de cifras decimales no determina por sí sola cuál número es mayor. Por ejemplo, 0,9 es mayor que 0,875, aunque tenga menos cifras.","data":{},"sort_order":3},{"lesson_id":"school-5b-frac-11","block_type":"concepts","title":"Conceptos fundamentales","content":"","data":{"items":[{"title":"Parte entera","body":"Se compara antes que cualquier posición decimal."},{"title":"Décimos","body":"Primera posición a la derecha de la coma."},{"title":"Centésimos","body":"Segunda posición a la derecha de la coma."},{"title":"Milésimos","body":"Tercera posición a la derecha de la coma."}]},"sort_order":4},{"lesson_id":"school-5b-frac-11","block_type":"math_model","title":"Modelo matemático visual","content":"","data":{"mode":"decimal_place_value","value":"12,305","caption":"12,305 contiene 12 unidades, 3 décimos, 0 centésimos y 5 milésimos."},"sort_order":5},{"lesson_id":"school-5b-frac-11","block_type":"formula","title":"Relaciones y procedimientos","content":"","data":{"items":["0,7 = 0,70 = 0,700","Compara: unidades → décimos → centésimos → milésimos","0,1 = 10/100 = 100/1000","0,01 = 10/1000","0,001 es una milésima"]},"sort_order":6},{"lesson_id":"school-5b-frac-11","block_type":"strategy","title":"Método MathLabs","content":"Aplica estos pasos antes de responder.","data":{"steps":[{"title":"1. Alinea las comas","body":"Escribe los números uno debajo del otro."},{"title":"2. Completa con ceros","body":"Iguala la cantidad de posiciones decimales si ayuda."},{"title":"3. Compara desde la izquierda","body":"La primera posición diferente decide."},{"title":"4. Usa la recta numérica","body":"Comprueba visualmente el orden."},{"title":"5. Explica la posición decisiva","body":"No basta con indicar el símbolo."}]},"sort_order":7},{"lesson_id":"school-5b-frac-11","block_type":"examples","title":"Ejercicios resueltos: nivel fundamental","content":"","data":{"examples":[{"problem":"Compara 0,7 y 0,67.","steps":["Escribimos 0,7 como 0,70.","Comparamos centésimos: 70 centésimos y 67 centésimos."],"answer":"0,7 > 0,67","skill":"Argumentar","level":"Fundamental","strategy":"Completa con ceros a la derecha.","verification":"En la recta, 0,70 está más cerca de 1."},{"problem":"Compara 1,205 y 1,25.","steps":["Igualamos posiciones: 1,205 y 1,250.","Unidades y décimos coinciden.","En centésimos, 0 es menor que 5."],"answer":"1,205 < 1,25","skill":"Argumentar","level":"Fundamental","strategy":"Compara una posición a la vez.","verification":"1,205 está apenas sobre 1,2; 1,25 está a mitad entre 1,2 y 1,3."}]},"sort_order":8},{"lesson_id":"school-5b-frac-11","block_type":"examples","title":"Ejercicios resueltos: nivel intermedio","content":"","data":{"examples":[{"problem":"Ordena 0,305; 0,35 y 0,053.","steps":["Escribimos 0,305; 0,350; 0,053.","En décimos: 0,053 tiene 0, mientras los otros tienen 3.","Entre 0,305 y 0,350, los centésimos deciden."],"answer":"0,053 < 0,305 < 0,35","skill":"Representar","level":"Intermedio","strategy":"Alinea hasta milésimos.","verification":"La secuencia aumenta en la recta numérica."},{"problem":"¿Son iguales 2,4 y 2,400?","steps":["Los ceros a la derecha no agregan cantidad.","Ambos representan 2 unidades y 4 décimos."],"answer":"Sí, son iguales","skill":"Argumentar","level":"Intermedio","strategy":"Distingue ceros posicionales de ceros finales.","verification":"2,4=24/10 y 2,400=2400/1000; ambas se simplifican igual."}]},"sort_order":9},{"lesson_id":"school-5b-frac-11","block_type":"examples","title":"Ejercicios resueltos: desafío","content":"","data":{"examples":[{"problem":"Una tabla registra 1,48 m, 1,405 m y 1,5 m. Ordénalos.","steps":["Igualamos: 1,480; 1,405; 1,500.","Comparamos milésimos de metro por valor posicional."],"answer":"1,405 m < 1,48 m < 1,5 m","skill":"Modelar","level":"Desafío","strategy":"Conserva la unidad de medida.","verification":"1,5 m es el único que alcanza 1 metro y 5 décimos."},{"problem":"Encuentra un decimal entre 0,48 y 0,49.","steps":["Expresamos como milésimos: 0,480 y 0,490.","Cualquier valor entre 481 y 489 milésimos sirve."],"answer":"Por ejemplo, 0,485","skill":"Argumentar","level":"Desafío","strategy":"Agrega una posición decimal para encontrar valores intermedios.","verification":"0,480<0,485<0,490."}]},"sort_order":10},{"lesson_id":"school-5b-frac-11","block_type":"guided_practice","title":"Práctica guiada","content":"Intenta cada problema antes de abrir las pistas.","data":{"exercises":[{"problem":"Compara 3,09 y 3,9.","hints":["Escribe 3,9 como 3,90.","Compara décimos."],"steps":["3,09 tiene 0 décimos.","3,90 tiene 9 décimos."],"answer":"3,09 < 3,9","skill":"Argumentar"},{"problem":"Ordena 0,8; 0,08 y 0,808.","hints":["Completa con ceros hasta milésimos.","0,800; 0,080; 0,808."],"steps":["0,080 es menor.","0,800<0,808."],"answer":"0,08 < 0,8 < 0,808","skill":"Representar"},{"problem":"Escribe un número entre 2,34 y 2,35.","hints":["Usa milésimos.","Piensa en 2,340 y 2,350."],"steps":["Un ejemplo es 2,345."],"answer":"2,345","skill":"Argumentar"}]},"sort_order":11},{"lesson_id":"school-5b-frac-11","block_type":"common_errors","title":"Errores frecuentes","content":"","data":{"items":[{"title":"Pensar que más cifras significa mayor número","description":"0,9 es mayor que 0,875."},{"title":"Comparar como si no existiera la coma","description":"El valor depende de la posición, no solo de la secuencia de cifras."},{"title":"Mover la coma al agregar ceros","description":"Los ceros equivalentes se agregan a la derecha, sin cambiar la coma."},{"title":"Olvidar la parte entera","description":"2,01 es mayor que cualquier decimal cuya parte entera sea 1."}]},"sort_order":12},{"lesson_id":"school-5b-frac-11","block_type":"summary","title":"Dominio esperado","content":"","data":{"items":["Comparas primero la parte entera.","Usas décimos, centésimos y milésimos.","Agregas ceros equivalentes.","Ordenas listas de decimales.","Encuentras valores entre dos decimales."]},"sort_order":13},{"lesson_id":"school-5b-frac-11","block_type":"practice","title":"Practica este tema","content":"Continúa con una sesión de ocho preguntas y retroalimentación inmediata.","data":{},"sort_order":14},{"lesson_id":"school-5b-frac-12","block_type":"objective","title":"Meta de aprendizaje","content":"Resolver adiciones y sustracciones decimales alineando posiciones y explicando el significado de cada cifra.","data":{},"sort_order":1},{"lesson_id":"school-5b-frac-12","block_type":"prerequisites","title":"Antes de comenzar","content":"Revisa estas ideas antes de avanzar.","data":{"items":[{"title":"Valor posicional decimal","body":"Décimos se combinan con décimos, centésimos con centésimos."},{"title":"Adición y sustracción","body":"Se aplican los mismos principios de reagrupación."},{"title":"Estimación","body":"Ayuda a detectar errores de coma o cálculo."}]},"sort_order":2},{"lesson_id":"school-5b-frac-12","block_type":"text","title":"Comprensión profunda","content":"Para sumar o restar decimales deben alinearse las comas. Eso asegura que unidades se combinen con unidades, décimos con décimos y así sucesivamente.\n\nSe pueden agregar ceros a la derecha para completar posiciones: 1,2 puede escribirse 1,200. Luego se opera como con números naturales, manteniendo la coma en la columna correspondiente.\n\nAntes y después del cálculo conviene estimar. Si 3,45+1,2 es aproximadamente 3,5+1,2=4,7, una respuesta como 46,5 revela que la coma quedó mal ubicada.","data":{},"sort_order":3},{"lesson_id":"school-5b-frac-12","block_type":"concepts","title":"Conceptos fundamentales","content":"","data":{"items":[{"title":"Alineación","body":"Las comas deben quedar en la misma columna."},{"title":"Ceros equivalentes","body":"Permiten completar posiciones sin cambiar el valor."},{"title":"Reagrupación","body":"Diez milésimos forman un centésimo, y así sucesivamente."},{"title":"Estimación","body":"Controla la magnitud esperada del resultado."}]},"sort_order":4},{"lesson_id":"school-5b-frac-12","block_type":"math_model","title":"Modelo matemático visual","content":"","data":{"mode":"decimal_operation","top":"8,300","bottom":"2,750","operator":"−","result":"5,550","caption":"Las comas y posiciones decimales se alinean antes de operar."},"sort_order":5},{"lesson_id":"school-5b-frac-12","block_type":"formula","title":"Relaciones y procedimientos","content":"","data":{"items":["Alinea las comas","Completa con ceros a la derecha","Opera por columnas de igual valor","Conserva la coma en la misma columna","Estima antes de aceptar el resultado"]},"sort_order":6},{"lesson_id":"school-5b-frac-12","block_type":"strategy","title":"Método MathLabs","content":"Aplica estos pasos antes de responder.","data":{"steps":[{"title":"1. Estima","body":"Redondea para anticipar el tamaño de la respuesta."},{"title":"2. Alinea las comas","body":"Escribe unidades bajo unidades."},{"title":"3. Completa posiciones","body":"Agrega ceros equivalentes cuando sea útil."},{"title":"4. Opera por columnas","body":"Reagrupa respetando el valor posicional."},{"title":"5. Compara con la estimación","body":"Detecta errores de magnitud o signo."}]},"sort_order":7},{"lesson_id":"school-5b-frac-12","block_type":"examples","title":"Ejercicios resueltos: nivel fundamental","content":"","data":{"examples":[{"problem":"Calcula 3,45 + 1,2.","steps":["Escribimos 1,2 como 1,20.","Alineamos comas.","3,45+1,20=4,65."],"answer":"4,65","skill":"Resolver problemas","level":"Fundamental","strategy":"Completa centésimos.","verification":"3,45≈3,5 y 1,2; la suma cercana a 4,7 es coherente."},{"problem":"Calcula 8,3 − 2,75.","steps":["Escribimos 8,3 como 8,30.","Alineamos comas.","8,30−2,75=5,55."],"answer":"5,55","skill":"Resolver problemas","level":"Fundamental","strategy":"Agrega un cero equivalente.","verification":"5,55+2,75=8,30."}]},"sort_order":8},{"lesson_id":"school-5b-frac-12","block_type":"examples","title":"Ejercicios resueltos: nivel intermedio","content":"","data":{"examples":[{"problem":"Una compra cuesta $12,75 y otra $8,90. ¿Cuál es el total?","steps":["Alineamos 12,75 y 8,90.","Sumamos centésimos, décimos y unidades."],"answer":"$21,65","skill":"Modelar","level":"Intermedio","strategy":"El dinero usa dos posiciones decimales.","verification":"21,65−8,90=12,75."},{"problem":"Una cuerda de 6,4 m pierde 1,875 m. ¿Cuánto queda?","steps":["Escribimos 6,4 como 6,400.","Restamos 6,400−1,875."],"answer":"4,525 m","skill":"Modelar","level":"Intermedio","strategy":"Completa hasta milésimos.","verification":"4,525+1,875=6,400."}]},"sort_order":9},{"lesson_id":"school-5b-frac-12","block_type":"examples","title":"Ejercicios resueltos: desafío","content":"","data":{"examples":[{"problem":"Encuentra x si x+2,375=5,8.","steps":["Despejamos mediante la operación inversa.","x=5,800−2,375.","Restamos por columnas."],"answer":"x=3,425","skill":"Resolver problemas","level":"Desafío","strategy":"Usa la resta como operación inversa.","verification":"3,425+2,375=5,800."},{"problem":"Un alumno calcula 4,7+0,38=4,108. Explica el error.","steps":["No alineó las posiciones decimales.","4,7 debe escribirse 4,70.","4,70+0,38=5,08."],"answer":"La respuesta correcta es 5,08","skill":"Argumentar","level":"Desafío","strategy":"Analiza el valor posicional antes del algoritmo.","verification":"4,7+0,3 ya supera 5, por lo que 4,108 era imposible."}]},"sort_order":10},{"lesson_id":"school-5b-frac-12","block_type":"guided_practice","title":"Práctica guiada","content":"Intenta cada problema antes de abrir las pistas.","data":{"exercises":[{"problem":"Calcula 2,6 + 0,75.","hints":["Escribe 2,6 como 2,60.","Alinea las comas."],"steps":["2,60+0,75=3,35."],"answer":"3,35","skill":"Resolver problemas"},{"problem":"Calcula 10 − 3,486.","hints":["Escribe 10 como 10,000.","Resta hasta milésimos."],"steps":["10,000−3,486=6,514."],"answer":"6,514","skill":"Resolver problemas"},{"problem":"Una botella tiene 1,5 L y se usan 0,375 L. ¿Cuánto queda?","hints":["Completa 1,5 como 1,500.","Resta."],"steps":["1,500−0,375=1,125."],"answer":"1,125 L","skill":"Modelar"}]},"sort_order":11},{"lesson_id":"school-5b-frac-12","block_type":"common_errors","title":"Errores frecuentes","content":"","data":{"items":[{"title":"Alinear últimas cifras en vez de comas","description":"Eso mezcla décimos con centésimos."},{"title":"Agregar ceros a la izquierda de la parte decimal","description":"0,5 puede escribirse 0,50, no 0,05."},{"title":"Olvidar la coma en el resultado","description":"Debe quedar en la misma columna que las comas de los datos."},{"title":"Aceptar un resultado sin estimar","description":"Una estimación rápida detecta errores de diez o cien veces."}]},"sort_order":12},{"lesson_id":"school-5b-frac-12","block_type":"summary","title":"Dominio esperado","content":"","data":{"items":["Alineas correctamente las comas.","Completas posiciones con ceros equivalentes.","Reagrupas por valor posicional.","Resuelves contextos de dinero y medición.","Compruebas con estimación y operación inversa."]},"sort_order":13},{"lesson_id":"school-5b-frac-12","block_type":"practice","title":"Practica este tema","content":"Continúa con una sesión de ocho preguntas y retroalimentación inmediata.","data":{},"sort_order":14},{"lesson_id":"school-5b-frac-13","block_type":"objective","title":"Meta de aprendizaje","content":"Seleccionar representaciones y operaciones adecuadas para resolver problemas contextualizados con fracciones y decimales.","data":{},"sort_order":1},{"lesson_id":"school-5b-frac-13","block_type":"prerequisites","title":"Antes de comenzar","content":"Revisa estas ideas antes de avanzar.","data":{"items":[{"title":"Equivalencias","body":"Permiten trabajar con una representación común."},{"title":"Suma y resta","body":"Debes operar fracciones y decimales con seguridad."},{"title":"Comprensión de problemas","body":"Distingue cantidad inicial, cambios y pregunta final."}]},"sort_order":2},{"lesson_id":"school-5b-frac-13","block_type":"text","title":"Comprensión profunda","content":"Los problemas pueden expresar cantidades como fracciones, decimales o ambas. Antes de operar, es necesario decidir si conviene convertir todas las cantidades a fracciones o a decimales.\n\nLa elección depende de los números involucrados. Fracciones como 1/2, 1/4, 3/4, 1/5 y décimos tienen conversiones exactas sencillas. Mantener una representación exacta evita redondeos innecesarios.\n\nUna solución completa no es solo una operación. Debe explicar qué representa cada cálculo, conservar las unidades y comprobar que la respuesta sea posible dentro del contexto.","data":{},"sort_order":3},{"lesson_id":"school-5b-frac-13","block_type":"concepts","title":"Conceptos fundamentales","content":"","data":{"items":[{"title":"Representación común","body":"Las cantidades deben expresarse de forma compatible antes de operar."},{"title":"Cantidad inicial","body":"Es la base desde la que se agregan o quitan partes."},{"title":"Resultado intermedio","body":"Cada etapa debe interpretarse antes de continuar."},{"title":"Unidad de medida","body":"Debe acompañar los cálculos y la respuesta final."}]},"sort_order":4},{"lesson_id":"school-5b-frac-13","block_type":"math_model","title":"Modelo matemático visual","content":"","data":{"mode":"fraction_decimal_match","fraction_numerator":3,"fraction_denominator":4,"decimal":"0,75","caption":"Elegir una representación común permite combinar información fraccionaria y decimal."},"sort_order":5},{"lesson_id":"school-5b-frac-13","block_type":"formula","title":"Relaciones y procedimientos","content":"","data":{"items":["Parte restante = total − parte utilizada","Cambio total = suma de cambios positivos y negativos","Convierte antes de operar si las representaciones son distintas","Mantén la unidad en cada resultado intermedio","Comprueba que la respuesta esté dentro del rango posible"]},"sort_order":6},{"lesson_id":"school-5b-frac-13","block_type":"strategy","title":"Método MathLabs","content":"Aplica estos pasos antes de responder.","data":{"steps":[{"title":"1. Identifica el todo","body":"Define qué representa una unidad completa."},{"title":"2. Clasifica los cambios","body":"Decide qué se agrega, se usa, se recorre o queda."},{"title":"3. Elige representación común","body":"Fracción o decimal, según cuál simplifique el problema."},{"title":"4. Resuelve por etapas","body":"Interpreta cada resultado intermedio."},{"title":"5. Comprueba y comunica","body":"Verifica rango, unidad y sentido contextual."}]},"sort_order":7},{"lesson_id":"school-5b-frac-13","block_type":"examples","title":"Ejercicios resueltos: nivel fundamental","content":"","data":{"examples":[{"problem":"Se recorrió 3/4 de una ruta y luego 0,15 de la ruta. ¿Qué parte se recorrió en total?","steps":["Convertimos 3/4=0,75.","Sumamos 0,75+0,15=0,90."],"answer":"0,90 de la ruta, equivalente a 9/10","skill":"Modelar","level":"Fundamental","strategy":"Convierte la fracción a decimal exacto.","verification":"El total es menor que 1, por lo que no se completó toda la ruta."},{"problem":"Una jarra contiene 1,5 L y se sirven 3/4 L. ¿Cuánto queda?","steps":["Convertimos 3/4=0,75.","Calculamos 1,50−0,75."],"answer":"0,75 L","skill":"Modelar","level":"Fundamental","strategy":"Usa una representación común.","verification":"0,75+0,75=1,50."}]},"sort_order":8},{"lesson_id":"school-5b-frac-13","block_type":"examples","title":"Ejercicios resueltos: nivel intermedio","content":"","data":{"examples":[{"problem":"Un libro se leyó 2/5 el lunes y 0,35 el martes. ¿Qué parte falta?","steps":["2/5=0,4.","Leído: 0,4+0,35=0,75.","Falta 1−0,75=0,25."],"answer":"0,25 del libro, equivalente a 1/4","skill":"Modelar","level":"Intermedio","strategy":"Calcula primero la parte acumulada.","verification":"0,75+0,25=1."},{"problem":"Una tabla mide 2,4 m. Se cortan 3/5 m y luego 0,45 m. ¿Cuánto queda?","steps":["3/5=0,6.","Corte total: 0,6+0,45=1,05.","Resto: 2,40−1,05=1,35."],"answer":"1,35 m","skill":"Modelar","level":"Intermedio","strategy":"Convierte a decimales exactos y conserva metros.","verification":"1,35+1,05=2,40."}]},"sort_order":9},{"lesson_id":"school-5b-frac-13","block_type":"examples","title":"Ejercicios resueltos: desafío","content":"","data":{"examples":[{"problem":"Un depósito estaba a 7/10 de su capacidad. Se agregan 0,18 y se usa 1/4 de la capacidad total. ¿Qué parte queda?","steps":["7/10=0,70 y 1/4=0,25.","Después de agregar: 0,70+0,18=0,88.","Después de usar: 0,88−0,25=0,63."],"answer":"0,63 de la capacidad","skill":"Modelar","level":"Desafío","strategy":"Mantén todas las cantidades respecto de la capacidad total.","verification":"El resultado está entre 0 y 1."},{"problem":"Una receta requiere 3/4 kg de harina. Hay una bolsa de 1,2 kg y se quieren preparar dos recetas. ¿Alcanza?","steps":["Dos recetas requieren 2·3/4=6/4=1,5 kg.","La bolsa contiene 1,2 kg.","Faltan 1,5−1,2=0,3 kg."],"answer":"No alcanza; faltan 0,3 kg","skill":"Argumentar","level":"Desafío","strategy":"Compara necesidad total con disponibilidad.","verification":"1,2 kg es menor que 1,5 kg."}]},"sort_order":10},{"lesson_id":"school-5b-frac-13","block_type":"guided_practice","title":"Práctica guiada","content":"Intenta cada problema antes de abrir las pistas.","data":{"exercises":[{"problem":"Una botella tiene 2 L y se usan 1/4 L y 0,6 L. ¿Cuánto queda?","hints":["Convierte 1/4 a decimal.","Suma lo usado y resta a 2."],"steps":["1/4=0,25.","Usado: 0,25+0,60=0,85.","Queda 2,00−0,85=1,15."],"answer":"1,15 L","skill":"Modelar"},{"problem":"Se completa 0,45 de una tarea en la mañana y 2/5 en la tarde. ¿Se termina?","hints":["Convierte 2/5.","Suma ambas partes."],"steps":["2/5=0,4.","0,45+0,40=0,85."],"answer":"No; falta 0,15","skill":"Modelar"},{"problem":"Un rollo de 3,5 m pierde 3/4 m y luego 1,2 m. ¿Cuánto queda?","hints":["Convierte 3/4 a 0,75.","Suma los cortes."],"steps":["0,75+1,20=1,95.","3,50−1,95=1,55."],"answer":"1,55 m","skill":"Modelar"}]},"sort_order":11},{"lesson_id":"school-5b-frac-13","block_type":"common_errors","title":"Errores frecuentes","content":"","data":{"items":[{"title":"Operar fracción y decimal sin convertir","description":"Primero deben expresarse en una representación compatible."},{"title":"Cambiar la unidad de referencia","description":"Todas las fracciones deben referirse al mismo todo."},{"title":"Redondear conversiones exactas","description":"1/4=0,25 exactamente; no es necesario aproximar."},{"title":"Responder un resultado intermedio","description":"En problemas de varias etapas hay que volver a la pregunta final."}]},"sort_order":12},{"lesson_id":"school-5b-frac-13","block_type":"summary","title":"Dominio esperado","content":"","data":{"items":["Identificas el todo y las unidades.","Eliges entre fracción y decimal.","Conviertes cantidades exactamente.","Resuelves problemas de varias etapas.","Compruebas que la respuesta sea posible."]},"sort_order":13},{"lesson_id":"school-5b-frac-13","block_type":"practice","title":"Practica este tema","content":"Continúa con una sesión de ocho preguntas y retroalimentación inmediata.","data":{},"sort_order":14}]$blocks$::jsonb)
as x(lesson_id text, block_type text, title text, content text, data jsonb, sort_order integer);

